package com.example.smsc;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.Arrays;import java.util.concurrent.atomic.AtomicLong;
/** Small local SMPP test endpoint: bind and submit_sm response only; no carrier delivery. */
public class SmscSimulator {
 private static final AtomicLong IDS=new AtomicLong(1000);public static void main(String[]a)throws Exception{int port=a.length>0?Integer.parseInt(a[0]):2775;String user=a.length>1?a[1]:"test",pass=a.length>2?a[2]:"test";try(ServerSocket server=new ServerSocket(port)){System.out.println("\u001B[36mSMSC SIMULATOR listening on 0.0.0.0:"+port+" systemId="+user+"\u001B[0m");while(true){Socket s=server.accept();new Thread(()->handle(s,user,pass),"smsc-session").start();}}}
 private static void handle(Socket s,String user,String pass){try(s;DataInputStream in=new DataInputStream(new BufferedInputStream(s.getInputStream()));DataOutputStream out=new DataOutputStream(new BufferedOutputStream(s.getOutputStream()))){while(true){int len;try{len=in.readInt();}catch(EOFException e){break;}if(len<16||len>1048576)throw new IOException("Bad PDU length="+len);int cmd=in.readInt(),status=in.readInt(),seq=in.readInt();byte[] body=in.readNBytes(len-16);if(body.length!=len-16)throw new EOFException();if(cmd==1||cmd==2||cmd==9){Cur c=new Cur(body);String id=c.cs(),pw=c.cs();boolean ok=user.equals(id)&&pass.equals(pw);write(out,cmd|0x80000000,ok?0:14,seq,ok?new byte[]{'S','M','S','C',0}:new byte[0]);System.out.println((ok?"BIND_OK ":"BIND_REJECT ")+id);}else if(cmd==4){Cur c=new Cur(body);c.cs();c.u();c.u();c.cs();c.u();c.u();c.cs();int esm=c.u();c.u();c.u();c.cs();c.cs();c.u();c.u();c.u();c.u();int n=c.u();byte[] msg=c.bytes(n);String mid=Long.toString(IDS.incrementAndGet(),36).toUpperCase();write(out,0x80000004,0,seq,(mid+"\0").getBytes(StandardCharsets.US_ASCII));System.out.println("\u001B[33mSUBMIT_SM\u001B[0m seq="+seq+" esm="+esm+" bytes="+n+" text="+new String(msg,StandardCharsets.ISO_8859_1));System.out.println("\u001B[32mSUBMIT_SM_RESP\u001B[0m seq="+seq+" status=0 messageId="+mid);}else if(cmd==0x15)write(out,0x80000015,0,seq,new byte[0]);else if(cmd==6){write(out,0x80000006,0,seq,new byte[0]);break;}else write(out,cmd|0x80000000,3,seq,new byte[0]);}}catch(Exception e){System.out.println("SESSION CLOSED: "+e.getMessage());}}
 private static void write(DataOutputStream o,int cmd,int st,int seq,byte[] b)throws IOException{o.writeInt(16+b.length);o.writeInt(cmd);o.writeInt(st);o.writeInt(seq);o.write(b);o.flush();}
 static class Cur{byte[]b;int p;Cur(byte[]b){this.b=b;}int u()throws IOException{if(p>=b.length)throw new EOFException();return b[p++]&255;}String cs()throws IOException{int s=p;while(p<b.length&&b[p]!=0)p++;if(p>=b.length)throw new EOFException();String x=new String(b,s,p-s,StandardCharsets.ISO_8859_1);p++;return x;}byte[]bytes(int n)throws IOException{if(p+n>b.length)throw new EOFException();byte[]x=Arrays.copyOfRange(b,p,p+n);p+=n;return x;}}
}
